exercises.solution:
IMC_MINIMO_NORMAL = 18.5
IMC_MAXIMO_NORMAL = 25


def a_numero(texto):
    return float(texto.replace(",", "."))


def calcular_imc(peso_kg, altura_cm):
    altura_m = altura_cm / 100
    return round(peso_kg / altura_m ** 2, 1)


def es_saludable(imc):
    return IMC_MINIMO_NORMAL <= imc < IMC_MAXIMO_NORMAL


def peso_saludable(altura_cm):
    altura_m = altura_cm / 100
    minimo = IMC_MINIMO_NORMAL * altura_m ** 2
    maximo = IMC_MAXIMO_NORMAL * altura_m ** 2
    return f"de {minimo:.1f} a {maximo:.1f} kg"


def main():
    nombre = input("Nombre: ").strip()
    peso = a_numero(input("Peso (kg): "))
    altura = a_numero(input("Altura (cm): "))
    imc = calcular_imc(peso, altura)
    print(f"=== Ficha de {nombre} ===")
    print(f"IMC: {imc}")
    print(f"Saludable: {es_saludable(imc)}")
    print(f"Peso saludable: {peso_saludable(altura)}")

