def _comparar_salida(salida, esperado):
    obtenidas = salida.split("\n")
    esperadas = esperado.split("\n")
    for i in range(max(len(obtenidas), len(esperadas))):
        o = obtenidas[i] if i < len(obtenidas) else "(nada)"
